sp_widget.server_script:
api.controller = 'FundEavorChatCtrl';
api.templateUrl = 'fundeavor_chat_widget.html';

api.onInit = function() {
    api.user_id = gs.getUserID();
    api.user_name = gs.getUser().getName();
};

api.getRecentCampaigns = function() {
    var gr = new GlideRecord('x_adsr_fundeavor_campaign');
    gr.addQuery('status', 'Published');
    gr.orderByDesc('sys_created_on');
    gr.setLimit(3);
    gr.query();

    var campaigns = [];
    while (gr.next()) {
        campaigns.push({
            number: gr.getValue('number'),
            title: gr.getValue('title'),
            target: gr.getValue('target')
        });
    }
    return campaigns;
};
